&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de r&#244;deur&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_r&#244;deur_0&quot; href=&quot;#Les_arch&#233;types_de_r&#244;deur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-R&#244;deur-(R&#244;deur).html&quot; title=&quot;Archer r&#244;deur&quot;&gt;Archer r&#244;deur&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-Des-Profondeurs-(R&#244;deur).html&quot; title=&quot;Arpenteur des profondeurs&quot;&gt;Arpenteur des profondeurs&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Briseur-De-Guildes-(R&#244;deur).html&quot; title=&quot;Briseur de guildes&quot;&gt;Briseur de guildes&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Rebelle-(R&#244;deur).html&quot; title=&quot;Champion rebelle&quot;&gt;Champion rebelle&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changeforme-(R&#244;deur).html&quot; title=&quot;Changeforme&quot;&gt;Changeforme&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Troph&#233;es-(R&#244;deur).html&quot; title=&quot;Chasseur de troph&#233;es&quot;&gt;Chasseur de troph&#233;es&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Sauvage-(R&#244;deur).html&quot; title=&quot;Chasseur sauvage&quot;&gt;Chasseur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dandy-(R&#244;deur).html&quot; title=&quot;Dandy&quot;&gt;Dandy&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;claireur-De-Larm&#233;e-(R&#244;deur).html&quot; title=&quot;&#201;claireur de l&amp;#39;arm&#233;e&quot;&gt;&#201;claireur de l&#39;arm&#233;e&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fauconnier-(R&#244;deur).html&quot; title=&quot;Fauconnier&quot;&gt;Fauconnier&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flibustier-(R&#244;deur).html&quot; title=&quot;Flibustier&quot;&gt;Flibustier&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-(R&#244;deur).html&quot; title=&quot;Gardien&quot;&gt;Gardien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Des-Vagues-(R&#244;deur).html&quot; title=&quot;Gardien des vagues&quot;&gt;Gardien des vagues&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Poisson-(Race).html&quot; title=&quot;Les hommes-poissons&quot;&gt;Homme-poisson&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-(R&#244;deur).html&quot; title=&quot;Guide&quot;&gt;Guide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-B&#234;tes-(R&#244;deur).html&quot; title=&quot;Ma&#238;tre des b&#234;tes&quot;&gt;Ma&#238;tre des b&#234;tes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Messager-Secret-(R&#244;deur).html&quot; title=&quot;Messager secret&quot;&gt;Messager secret&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ombre-Sauvage-(R&#244;deur).html&quot; title=&quot;Ombre sauvage&quot;&gt;Ombre sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pisteur-Divin-(R&#244;deur).html&quot; title=&quot;Pisteur divin&quot;&gt;Pisteur divin&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Infiltr&#233;-(R&#244;deur).html&quot; title=&quot;R&#244;deur infiltr&#233;&quot;&gt;R&#244;deur infiltr&#233;&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Libre-Du-Nirmathas-(R&#244;deur).html&quot; title=&quot;R&#244;deur libre des for&#234;ts&quot;&gt;R&#244;deur libre des for&#234;ts&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Spirituel-(R&#244;deur).html&quot; title=&quot;R&#244;deur spirituel&quot;&gt;R&#244;deur spirituel&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Urbain-(R&#244;deur).html&quot; title=&quot;R&#244;deur urbain&quot;&gt;R&#244;deur urbain&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-Des-Chevaux-(R&#244;deur).html&quot; title=&quot;Seigneur des chevaux&quot;&gt;Seigneur des chevaux&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sentinelle-(R&#244;deur).html&quot; title=&quot;Sentinelle&quot;&gt;Sentinelle&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tirailleur-(R&#244;deur).html&quot; title=&quot;Tirailleur&quot;&gt;Tirailleur&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transporteur-(R&#244;deur).html&quot; title=&quot;Transporteur&quot;&gt;Transporteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-(R&#244;deur).html&quot; title=&quot;Trappeur&quot;&gt;Trappeur&lt;/a&gt; (UM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Du-Cr&#233;puscule-(R&#244;deur).html&quot; title=&quot;Traqueur du cr&#233;puscule&quot;&gt;Traqueur du cr&#233;puscule&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Fetchelin-(Race).html&quot; title=&quot;Les fetchelins&quot;&gt;Fetchelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Sauvage-(R&#244;deur).html&quot; title=&quot;Traqueur sauvage&quot;&gt;Traqueur sauvage&lt;/a&gt; (UC)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Antith&#232;se du b&#251;cheron bourru et sauvage, le dandy s&#39;efforce de ma&#238;triser l&#39;&#233;tiquette subtile des cours nobles, les murmures des sombres rumeurs et les coutumes du monde cultiv&#233;. Il n&#39;en reste pas moins un r&#244;deur dans l&#39;&#226;me, et il traque les rumeurs et les ragots dans les grandes salles de bal des riches et des puissants, tout comme la plupart des r&#244;deurs traquent leurs ennemis dans la nature.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_0&quot; href=&quot;#Comp&#233;tences_de_classe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un dandy ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (folklore local), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (noblesse), &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe, mais en retire &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (exploration souterraine), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) et &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;. Cela modifie les comp&#233;tences de classe du r&#244;deur.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Nation de pr&#233;dilection (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Nation_de_pr&#233;dilection_Ext_1&quot; href=&quot;#Nation_de_pr&#233;dilection_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Chaque fois qu&#39;il devrait choisir un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemi jur&#233;&lt;/a&gt;, un dandy choisit &#224; la place un pays dont il conna&#238;t parfaitement les usages de la cour. Il b&#233;n&#233;ficie d&#39;un bonus de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; contre les courtisans, les officiels, les nobles et l&#39;aristocratie de cette nation. De m&#234;me, il b&#233;n&#233;ficie d&#39;un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; contre eux.&lt;br /&gt;&lt;br /&gt;Un dandy peut effectuer des tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; appropri&#233;s sans formation pour identifier de telles personnes originaires du pays s&#233;lectionn&#233;. Un dandy gagne des nations de pr&#233;dilection suppl&#233;mentaires, et peut augmenter les bonus de l&#39;une de ses nations de pr&#233;dilection actuelles, de la m&#234;me mani&#232;re qu&#39;il le ferait avec l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemi jur&#233;&lt;/a&gt; d&#39;un r&#244;deur normal. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemi jur&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Empathie comm&#232;re (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Empathie_comm&#232;re_Ext_2&quot; href=&quot;#Empathie_comm&#232;re_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un dandy peut modifier le flux et la propagation des rumeurs en sa faveur. Cette capacit&#233; fonctionne de mani&#232;re similaire &#224; l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#EMPATHIESAUVAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;empathie sauvage&lt;/a&gt;, sauf qu&#39;elle n&#233;cessite 1 jour (8 heures de travail), au lieu de 1 minute, et qu&#39;elle affecte la teneur g&#233;n&#233;rale d&#39;une rumeur au lieu d&#39;un animal sauvage.&lt;br /&gt;&lt;br /&gt;Un test d&#39;empathie comm&#232;re r&#233;ussi permet au dandy d&#39;augmenter ou de diminuer d&#39;un cran le ton de la rumeur. Par exemple, il peut rendre une rumeur indiff&#233;rente amicale et donc positive envers sa cible, ou une rumeur inamicale hostile et donc encore plus n&#233;gative envers sa cible qu&#39;elle ne l&#39;&#233;tait &#224; l&#39;origine.&lt;br /&gt;&lt;br /&gt;La difficult&#233; d&#39;influencer une rumeur d&#233;pend de la taille de la communaut&#233; dans laquelle elle se r&#233;pand. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du test est de 15 dans un &lt;a class=&quot;pagelink&quot; href=&quot;Villes.html#Les_communaut&#233;s_dans_le_jeu_9&quot; title=&quot;Les villes et communaut&#233;s&quot;&gt;village&lt;/a&gt; ou une communaut&#233; plus petite. Ce DD augmente de 5 et le nombre de jours n&#233;cessaires pour tenter le test augmente de 2 pour chaque cat&#233;gorie de taille de communaut&#233; sup&#233;rieure &#224; un village, jusqu&#39;&#224; un maximum de DD 40 et 11 jours pour affecter une rumeur se propageant dans une m&#233;tropole enti&#232;re.&lt;br /&gt;&lt;br /&gt;Si la rumeur ne se r&#233;pand qu&#39;&#224; travers une plus petite partie de la population, comme le quartier elfique d&#39;une plus grande m&#233;tropole, on utilise la population de cette plus petite partie pour d&#233;terminer le DD et le nombre de jours de travail requis pour utiliser empathie comm&#232;re. Le DD augmente &#233;galement de 10 si la rumeur concerne le dandy lui-m&#234;me, puisque le dandy est &#233;videmment une source partiale en ce qui concerne les rumeurs qui courent sur sa propre personne. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#EMPATHIESAUVAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;empathie sauvage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Environnement de pr&#233;dilection (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Environnement_de_pr&#233;dilection_Ext_3&quot; href=&quot;#Environnement_de_pr&#233;dilection_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, un dandy gagne &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt; (urbain), et bien que la capacit&#233; continue &#224; s&#39;am&#233;liorer aux m&#234;mes niveaux, il ne gagne pas d&#39;environnement suppl&#233;mentaire. Cependant, au niveau 8, chaque fois qu&#39;il participe &#224; une r&#233;ception ou une f&#234;te de cour, ses bonus d&#39;environnement de pr&#233;dilection augmentent de 2 points suppl&#233;mentaires. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Fr&#233;quentations (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Fr&#233;quentations_Ext_4&quot; href=&quot;#Fr&#233;quentations_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, un dandy doit choisir ses alli&#233;s comme &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PACTEDUCHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;pacte du chasseur&lt;/a&gt;, et pas un compagnon animal. En plus de la capacit&#233; habituelle de pacte du chasseur, le dandy peut passer 10 minutes lors d&#39;un &#233;v&#233;nement ou d&#39;une f&#234;te particuli&#232;re &#224; papoter et &#224; pr&#233;senter ses alli&#233;s aux bonnes personnes afin de leur accorder la moiti&#233; de ses bonus de nation de pr&#233;dilection aux comp&#233;tences (mais pas les bonus aux jets d&#39;attaque et de d&#233;g&#226;ts) pour la dur&#233;e de l&#39;&#233;v&#233;nement. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PACTEDUCHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;pacte du chasseur&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sorts de dandy (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_de_dandy_Sur_5&quot; href=&quot;#Sorts_de_dandy_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le dandy acquiert un type de lancement de sorts diff&#233;rent de celui de la plupart des r&#244;deurs. Un dandy utilise son &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; plut&#244;t que sa &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; pour d&#233;terminer ses sorts par jour, leur DD, et les autres facteurs li&#233;s au lancement de sorts. Il lance des sorts spontan&#233;ment &#224; partir de la &lt;a class=&quot;pagelink&quot; href=&quot;Liste-Des-Sorts-De-Bardes.html&quot; title=&quot;Liste des sorts de barde&quot;&gt;liste des sorts du barde&lt;/a&gt; (plut&#244;t que de la &lt;a class=&quot;pagelink&quot; href=&quot;Liste-Des-Sorts-De-R&#244;deurs.html&quot; title=&quot;Liste des sorts de r&#244;deur&quot;&gt;liste des sorts du r&#244;deur&lt;/a&gt;), avec le m&#234;me nombre de sorts connus et de sorts par jour qu&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html&quot; title=&quot;Le m&#233;dium&quot;&gt;m&#233;dium&lt;/a&gt; de son niveau de r&#244;deur. Cette capacit&#233; modifie les &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#SORTS&quot; title=&quot;Le r&#244;deur&quot;&gt;sorts du r&#244;deur&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Trouble-f&#234;te (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Trouble-f&#234;te_Ext_6&quot; href=&quot;#Trouble-f&#234;te_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 7, le dandy est capable de se frayer un chemin dans les f&#234;tes chic, les bals royaux et autres &#233;v&#233;nements sociaux destin&#233;s &#224; la bourgeoisie. Pour ce faire, il doit effectuer un test de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 25 et y consacrer 1d4 heures. S&#39;il r&#233;ussit, il se trouve une invitation, un invit&#233; cherchant un rendez-vous, un membre du personnel pr&#234;t &#224; regarder ailleurs, ou un autre moyen d&#39;entrer dans la f&#234;te. Cela ne lui permet pas de s&#39;introduire dans des zones restreintes ou d&#39;infiltrer des rassemblements strictement ferm&#233;s, comme des r&#233;unions secr&#232;tes ; cela lui permet uniquement d&#39;acc&#233;der &#224; des &#233;v&#233;nements sociaux. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#DEPLACEMENTFACILITE&quot; title=&quot;Le r&#244;deur&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt;.
